+```ts
+/**
+ * The walk-up predicate: rows granted at the requested scope point or above it.
+ * Exported for unit testing the level branching; not used outside this module.
+ */
+export function buildScopePredicate(
+	eb: ExpressionBuilder<Database, "user_role_assignments">,
+	scope: { accountId: number; siteId?: number; storeId?: number },
+) {
+	const clauses = [
+		eb.and([
+			eb("account_id", "is", null),
+			eb("site_id", "is", null),
+			eb("store_id", "is", null),
+		]),
+		eb.and([
+			eb("account_id", "=", scope.accountId),
+			eb("site_id", "is", null),
+			eb("store_id", "is", null),
+		]),
+	];
+	if (scope.siteId != null) {
+		clauses.push(
+			eb.and([
+				eb("account_id", "=", scope.accountId),
+				eb("site_id", "=", scope.siteId),
+				eb("store_id", "is", null),
+			]),
+		);
+		if (scope.storeId != null) {
+			clauses.push(
+				eb.and([
+					eb("account_id", "=", scope.accountId),
+					eb("site_id", "=", scope.siteId),
+					eb("store_id", "=", scope.storeId),
+				]),
+			);
+		}
+	}
+	return eb.or(clauses);
+}
+
+/**
+ * One page of users whose grants reach the requested scope point, plus every
+ * assignment those users hold.
+ *
+ * The scope predicate is applied only when choosing which users are on the
+ * page. The second query is deliberately unfiltered so each assignment
+ * reassembles with its complete scope arrays — callers must return assignments
+ * unmodified, and filtering rows here would silently truncate a fan-out.
+ */
+export async function listScopedAssignmentPage(
+	db: Kysely<Database>,
+	opts: {
+		organizationId: string;
+		environment: Environment;
+		accountId: number;
+		siteId?: number;
+		storeId?: number;
+		limit: number;
+		cursor?: string;
+	},
+): Promise<{
+	userIds: string[];
+	assignments: IamRoleAssignment[];
+	nextCursor: string | null;
+	hasMore: boolean;
+}> {
+	let userQuery = db
+		.selectFrom("user_role_assignments")
+		.select("user_id")
+		.distinct()
+		.where("organization_id", "=", opts.organizationId)
+		.where("environment", "=", opts.environment)
+		.where((eb) => buildScopePredicate(eb, opts))
+		.orderBy("user_id", "asc")
+		.limit(opts.limit + 1);
+
+	const decoded = opts.cursor ? decodeCursor(opts.cursor) : null;
+	if (decoded) {
+		userQuery = userQuery.where("user_id", ">", decoded.id);
+	}
+
+	const userRows = await userQuery.execute();
+	const hasMore = userRows.length > opts.limit;
+	const pageRows = hasMore ? userRows.slice(0, opts.limit) : userRows;
+	const userIds = pageRows.map((r) => r.user_id);
+
+	if (userIds.length === 0) {
+		return { userIds: [], assignments: [], nextCursor: null, hasMore: false };
+	}
+
+	const rows = await db
+		.selectFrom("user_role_assignments as ura")
+		.innerJoin("roles", "roles.id", "ura.role_id")
+		.select([
+			"ura.id",
+			"ura.assignment_id",
+			"ura.user_id",
+			"ura.role_id",
+			"ura.organization_id",
+			"ura.environment",
+			"ura.account_id",
+			"ura.site_id",
+			"ura.store_id",
+			"ura.assigned_by",
+			"ura.assigned_at",
+			"roles.rank as role_rank",
+			"roles.slug as role_slug",
+			"roles.name as role_name",
+		])
+		.where("ura.organization_id", "=", opts.organizationId)
+		.where("ura.environment", "=", opts.environment)
+		.where("ura.user_id", "in", userIds)
+		.orderBy("ura.id", "desc")
+		.execute();
+
+	const lastUserId = userIds.at(-1);
+	return {
+		userIds,
+		assignments: roleAssignmentRowsToDomain(
+			rows as AssignmentRowWithRoleInfo[],
+		),
+		nextCursor: hasMore && lastUserId ? encodeCursor(lastUserId) : null,
+		hasMore,
+	};
+}
+```
