+		let call = 0;
+		const builder = (sink: Record<string, unknown>) => {
+			const qb: Record<string, unknown> = {
+				select: () => qb,
+				distinct: () => qb,
+				innerJoin: () => qb,
+				orderBy: () => qb,
+				limit: (n: number) => {
+					sink["limit"] = n;
+					return qb;
+				},
+				where: (a: unknown, op?: unknown, val?: unknown) => {
+					if (typeof a === "function") {
+						sink["predicateApplied"] = true;
+					} else {
+						sink[`where:${String(a)}`] = { op, val };
+					}
+					return qb;
+				},
+				execute: async () => (call++ === 0 ? userRows : assignmentRows),
+			};
+			return qb;
+		};
+		return {
+			db: {
+				selectFrom: () => {
+					const sink: Record<string, unknown> = {};
+					calls.push(sink);
