+			eb("site_id", "is", null),
+			eb("store_id", "is", null),
+		]),
+		eb.and([
+			eb("account_id", "=", scope.accountId),
+			eb("site_id", "is", null),
+			eb("store_id", "is", null),
+		]),
+	];
