+export type ScopeQuery = {
+	accountId: number;
+	siteId?: number;
+	storeId?: number;
+};
+
+/** The hierarchy level an assignment was granted at, read off its id arrays. */
+function assignmentHierarchyLevel(a: RoleAssignment): number {
+	return getHierarchyLevel({
+		accountId: a.accountIds[0],
+		siteId: a.siteIds[0],
+		storeId: a.storeIds[0],
+	});
+}
+
+/**
+ * True when `a` grants access at or above the scope point `q` — the walk-up
+ * rule. An assignment more specific than the query point does NOT match: a
+ * store-level grant confers no access to the whole site.
+ *
+ * Membership tests rather than equality, so a fanned-out assignment
+ * (store_ids [7,8,9]) matches a query for any one of its stores.
+ */
+export function roleAssignmentMatchesScope(
+	a: RoleAssignment,
+	q: ScopeQuery,
+): boolean {
+	const level = assignmentHierarchyLevel(a);
+	if (level === HIERARCHY_LEVEL.org) {
+		return true;
+	}
+	if (!a.accountIds.includes(q.accountId)) {
+		return false;
+	}
+	if (level === HIERARCHY_LEVEL.account) {
+		return true;
+	}
+	if (q.siteId == null || !a.siteIds.includes(q.siteId)) {
+		return false;
+	}
+	if (level === HIERARCHY_LEVEL.site) {
+		return true;
+	}
+	return q.storeId != null && a.storeIds.includes(q.storeId);
+}
+
+/**
+ * Per user, keep only the assignments granted at the deepest level. Ties at
+ * that level all survive. Assignments are returned untouched — callers rely on
+ * the winner keeping its full scope arrays.
+ */
+export function roleAssignmentMostSpecificPerUser(
+	assignments: IamRoleAssignment[],
+): IamRoleAssignment[] {
+	const buckets = Map.groupBy(assignments, (a) => a.userId);
+	return [...buckets.values()].flatMap((group) => {
+		const deepest = Math.max(...group.map(assignmentHierarchyLevel));
+		return group.filter((a) => assignmentHierarchyLevel(a) === deepest);
+	});
+}

