+
+/**
+ * Users with access at the requested scope point, one page at a time.
+ *
+ * IAM assignments only — the legacy fallback resolves *known* user ids against
+ * platform-framework and cannot enumerate, so it has no place on a discovery
+ * endpoint. Organizations without rolesv2 simply hold no IAM assignments.
+ */
+export async function listScopedAssignments(
+	db: Kysely<Database>,
+	opts: {
+		organizationId: string;
+		environment: Environment;
+		accountId: number;
+		siteId?: number;
+		storeId?: number;
+		limit: number;
+		cursor?: string;
+	},
+): Promise<{
+	userIds: string[];
+	assignments: IamRoleAssignment[];
+	nextCursor: string | null;
+	hasMore: boolean;
+}> {
+	if (opts.storeId != null && opts.siteId == null) {
+		throw new AssignmentServiceError(
+			400,
+			"invalid-scope",
+			"store_id requires site_id",
+		);
+	}
+
+	const page = await assignmentsDb.listScopedAssignmentPage(db, opts);
+
+	const inScope = page.assignments.filter((a) =>
+		roleAssignmentMatchesScope(a, {
+			accountId: opts.accountId,
+			siteId: opts.siteId,
+			storeId: opts.storeId,
+		}),
+	);
+	const winners = roleAssignmentMostSpecificPerUser(inScope);
+
+	// The SQL predicate and roleAssignmentMatchesScope encode the same rule, so
+	// this filter should be a no-op. Kept so a future divergence degrades into a
+	// shorter page rather than a user with an empty assignments array.
+	const withWinners = new Set(winners.map((a) => a.userId));
+
+	return {
+		userIds: page.userIds.filter((id) => withWinners.has(id)),
+		assignments: winners,
+		nextCursor: page.nextCursor,
+		hasMore: page.hasMore,
+	};
+}

